"""Write lib/patches.lua: the 30 approved audition patches (scripts/fascia_audition.py)
as full 32-control tables, plus MACHINE SEL's start.

    PYTHONPATH=../DN2-Rift/src:../DN2-Rift/scripts python3 ignore/dev/tools/gen_patches.py > lib/patches.lua
"""
import fascia_audition as A
from dnfw.fascia import live as L
from dnfw.fascia import model as M

names = list(M.INTERNAL)
out = ["-- generated by ignore/dev/tools/gen_patches.py from DN2-Rift's scripts/fascia_audition.py",
       "-- (the 30 patches approved on the pass-3 tour); do not edit by hand.",
       "-- values in RIFT's page order: " + " ".join(names),
       "local P = {}"]


def row(label, q, trem):
    vals = ", ".join(str(q[k]) for k in names)
    return f'P[#P + 1] = {{name = "{label}", trem = {trem}, v = {{{vals}}}}}'


out.append(row("init (vibraphone)", M.DEFAULTS, 0))
for key, (p, _e, _s, trem) in A.PATCHES.items():
    label = key.split("_", 1)[1].replace("_", " ")
    out.append(row(label, L.engine(p), trem))
out.append("return P")
print("\n".join(out))
